-- Changelog: kwaliteitsronde buitenschil + meerwerk reviseren na opdracht.
insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-08-31','nieuw','KAM/VGM','Kwaliteitsronde over de buitenschil',
   'Je loopt nu op je telefoon een kwaliteitsronde over een lopende opdracht. Je kiest welke onderdelen op dit moment te beoordelen zijn, krijgt alleen die controlepunten te zien, meet waar dat nodig is en legt afwijkingen met foto vast. Wat je invult wordt meteen bewaard. Op de desktop staan de rondes, de openstaande afwijkingen en de bibliotheek met kwaliteitseisen; van elke ronde maak je een kwaliteitsrapport.'),
  ('2026-08-31','verbeterd','Offertes','Meerwerkofferte reviseren na de opdracht',
   'Een verzonden meerwerkofferte kun je nu ook reviseren als de opdracht al loopt: je maakt er een nieuwe versie van en past die aan. De calculatie waarvoor de opdracht is gegeven blijft wel vergrendeld. De meerwerkregels tonen voortaan hun versienummer, zodat je de oude en de nieuwe versie uit elkaar houdt.');
